	private static void assertDeleteData(
			Function<ValueFactory, Resource> subjectFactory,
			String subjectSyntax, boolean explicitPhysicalDefault, boolean expectedNamedGraphPresent) {
		var repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var subject = subjectFactory.apply(vf);
			var predicate = vf.createIRI("urn:p");
			var object = vf.createLiteral("same");
			var graph = vf.createBNode("g");
			connection.add(subject, predicate, object);
			connection.add(subject, predicate, object, graph);
			var update = connection.prepareUpdate("DELETE DATA { " + subjectSyntax + " <urn:p> \"same\" }");
			if (explicitPhysicalDefault) {
				update.setDataset(physicalDefaultDataset());
			}
			update.execute();
			assertFalse(connection.hasStatement(subject, predicate, object, false, (Resource) null));
			assertEquals(expectedNamedGraphPresent,
					connection.hasStatement(subject, predicate, object, false, graph));
		} finally {
			repository.shutDown();
		}
	}

